import re

_NUMERIC = re.compile(r"\d+")


def _key(version):
    core, _, _build = version.partition("+")
    core, sep, pre = core.partition("-")
    major, minor, patch = (int(p) for p in core.split("."))

    if not sep:
        return (major, minor, patch, 1, ())

    identifiers = tuple(
        (0, int(part)) if _NUMERIC.fullmatch(part) else (1, part)
        for part in pre.split(".")
    )
    return (major, minor, patch, 0, identifiers)


def sort_versions(vs):
    return sorted(vs, key=_key)
